     "summary": "8月4日(星期二)，今日报刊头条主要内容精华如下： 中国证券报 上市药企密集公告 拟中选国家药品集采 8月3日，一品红、科源制药、立方制药、联环药业等近30家医药上市公司相继发布公告称，旗下多款药品拟中选第12批国家药品集采。上述企业表示，若公司拟中选产品后续签订采购合同并实施，将有利于进一步扩大相关产品的销售规模，提高市场占有率，提升公司品牌影响力，对公司的未来经营业绩具有积极影响，并将全力保障相关产品供应。 存储龙头股价“腰斩”！资金大分歧 8月3日，存储龙头兆易创新股价",
