     "summary": "当地时间8月3日，美国总统特朗普在白宫回答记者提问时表示，同伊朗的谈判目前正在进行中。 特朗普表示，关于与伊朗的谈判，第一阶段是开放霍尔木兹海峡，第二阶段是“无核化”。特朗普称，美国对此态度坚定，伊朗不能拥有核武器。此外，特朗普还透露了有关开放霍尔木兹海峡方面的谈判进展。特朗普称，霍尔木兹海峡可能最迟明天重开。 他还表示，谈判是应伊朗的要求，在沙特阿拉伯、阿联酋、卡塔尔还有其他一些国家的支持下进行的。他称，本来“美国要对伊朗进行猛烈打击，力度超过以往任何一次攻击”，结果伊朗方",
